function isMasterAdmin(){return state.cityContextReady?state.cityRole==='master':state.profile?.role==='admin'}
function isAdmin(){return state.cityContextReady?['admin','master'].includes(state.cityRole):state.profile?.role==='admin'}
async function loadCityContext(){
  state.cities=[];state.activeCityId=null;state.cityRole=null;state.cityContextReady=false;state.cityAccessError='';
  try{
    const {data,error}=await state.client.rpc('list_my_cities');
    if(error)throw error;
    state.cityContextReady=true;state.cities=data||[];
    if(!state.cities.length){state.cityAccessError='Sua conta ainda não foi vinculada a uma cidade.';return}
    let active=state.cities.find(city=>city.active);
    if(!active){
      active=state.cities[0];
      const changed=await state.client.rpc('set_active_city',{p_city_id:active.id});
      if(changed.error)throw changed.error;
    }
    state.activeCityId=active.id;state.cityRole=active.role;
  }catch(error){
    // Fail closed: a failed city lookup must never grant fallback/global access.
    state.cityContextReady=true;state.cityRole=null;state.activeCityId=null;state.cities=[];
    state.cityAccessError='Não foi possível validar a cidade atribuída. Tente novamente ou procure o administrador master.';
  }
}
