  $('#recordDialog').innerHTML='<button class="close" type="button" data-close aria-label="Fechar">×</button><div class="dialog-content"><p class="eyebrow">ATUALIZAÇÃO DE STATUS</p><h2>Informar mandado baixado</h2><p class="warrant-caution">A baixa será enviada para conferência do administrador. Se não tiver o número do documento oficial, você pode registrar sem ele.</p><form id="warrantReportForm" data-warrant-id="'+warrantId+'" class="warrant-form"><label>Data da baixa<input name="discharge_date" type="date" required max="'+today+'" value="'+today+'"></label><label>Referência oficial (opcional)<input name="reference" maxlength="200" placeholder="Número do documento, se disponível"></label><label>Observações (opcional)<textarea name="notes" rows="3" maxlength="1000" placeholder="Informações para ajudar na conferência"></textarea></label><div class="warrant-actions"><button class="button secondary" type="button" data-close>Cancelar</button><button class="button" type="submit">Enviar para conferência</button></div></form></div>';showTrackedDialog($('#recordDialog'));
