async function submitWarrantDeleteAll(event){
  event.preventDefault();
  if(!isAdmin())throw new Error('Apenas administradores podem excluir mandados.');
  const form=event.target,submit=event.submitter;
  if(String(new FormData(form).get('confirmation')||'').trim()!=='APAGAR TODOS')throw new Error('Digite APAGAR TODOS exatamente para confirmar.');
  if(submit)submit.disabled=true;
  try{
    const {data,error}=await state.client.rpc('admin_delete_all_arrest_warrants');
    if(error)throw error;
    const paths=[...new Set((Array.isArray(data?.storage_paths)?data.storage_paths:[]).filter(path=>typeof path==='string'&&path))];
    let storageWarning='';
    for(let offset=0;offset<paths.length;offset+=100){
      const {error:storageError}=await state.client.storage.from('warrant-documents').remove(paths.slice(offset,offset+100));
      if(storageError){storageWarning=' Os registros foram removidos, mas alguns PDFs privados não foram apagados do armazenamento.';break}
    }
    const deleted=Number(data?.deleted_count)||0;
    warrantSearchResults.clear();warrantEditRecords.clear();$('#recordDialog').close();
    toast(storageWarning?'Mandados excluídos ('+deleted+').'+storageWarning:'Todos os '+deleted+' mandados foram excluídos. O histórico de auditoria foi preservado.');
    await renderWarrants();
  }finally{if(submit&&$('#recordDialog')?.open)submit.disabled=false}
}
