async function readWarrantPdfBatch(files){
  if(!isAdmin())throw new Error('Apenas administradores podem importar peças.');
  if(warrantPdfBatchReading)throw new Error('Aguarde a leitura dos PDFs selecionados terminar.');
  const selected=[...files];
  if(!selected.length)return;
  if(warrantPdfBatch.length+selected.length>MAX_WARRANT_PDF_BATCH)throw new Error('A fila permite até '+MAX_WARRANT_PDF_BATCH+' PDFs por vez.');
  if([...warrantPdfBatch.map(row=>row.file),...selected].some(file=>file.size>MAX_WARRANT_PDF_FILE_BYTES))throw new Error('Cada PDF deve ter até '+Math.round(MAX_WARRANT_PDF_FILE_BYTES/1024/1024)+' MB.');
  const totalSize=[...warrantPdfBatch.map(row=>row.file),...selected].reduce((total,file)=>total+file.size,0);
  if(totalSize>MAX_WARRANT_PDF_BATCH_BYTES)throw new Error('A fila deve ter até '+Math.round(MAX_WARRANT_PDF_BATCH_BYTES/1024/1024)+' MB no total.');
  const startIndex=warrantPdfBatch.length;
  warrantPdfBatch.push(...selected.map(file=>({file,values:{source_agency:'BNMP'},status:'Aguardando leitura local…'})));
  warrantPdfBatchReading=true;
  try{
    await renderWarrants();
    document.querySelector('.warrant-pdf-batch-queue')?.scrollIntoView({block:'start',behavior:'smooth'});
    for(let index=startIndex;index<warrantPdfBatch.length;index++){
      const entry=warrantPdfBatch[index];
      try{
        if(entry.file.type!=='application/pdf'&&!/\.pdf$/i.test(entry.file.name))throw new Error('O arquivo não parece ser um PDF.');
        const result=await processOcrFiles([entry.file],{onProgress:progress=>warrantBatchStatus(index,'PDF '+(index+1)+' de '+warrantPdfBatch.length+' · '+formatWarrantOcrProgress(progress))});
        const suggestion=extractWarrantPersonSuggestions(result.text);
        entry.values={warrant_number:suggestion.warrant_number||'',full_name:suggestion.full_name||'',cpf:suggestion.cpf_digits||'',person_rg:suggestion.rg||'',birth_date:suggestion.birth_date||'',person_address_primary:suggestion.address_primary||'',source_reference:suggestion.process_reference||'',source_agency:'BNMP',person_filiation:suggestion.filiation||'',person_process_information:suggestion.process_information||''};
        entry.status=result.text?'Leitura concluída. Confira e complete os campos.':'PDF processado, mas nenhum texto foi identificado. Preencha os campos manualmente.';
        warrantBatchStatus(index,entry.status);
      }catch(error){entry.status='Falha na leitura: '+msg(error);warrantBatchStatus(index,entry.status)}
    }
  }finally{
    warrantPdfBatchReading=false;
    await renderWarrants();
  }
}
async function saveWarrantPdfBatch(){
  if(!isAdmin())throw new Error('Apenas administradores podem salvar mandados.');
  if(warrantPdfBatchReading)throw new Error('Aguarde a leitura dos PDFs terminar antes de salvar.');
  if(warrantPdfBatchSaving) return;
  if(!warrantPdfBatch.length)throw new Error('Selecione ao menos um PDF.');
  warrantPdfBatchSaving=true;
  const initialCount=warrantPdfBatch.length;let saved=0,failed=0,partial=0,reviewCount=0,duplicateCount=0;
  try{
    for(let index=0;index<warrantPdfBatch.length;index++){
      const entry=warrantPdfBatch[index],row=document.querySelector('[data-warrant-pdf-batch-row="'+index+'"]');
      const fields=['warrant_number','full_name','cpf','person_rg','birth_date','person_address_primary','source_agency','source_reference','person_filiation','person_process_information'];
      const editedValues={};
      for(const name of fields){const input=row?.querySelector('[name="'+name+'"]');if(input)editedValues[name]=input.value}
      const values=resolveWarrantBatchValues(entry.values,editedValues,fields);
      entry.values=values;
      warrantBatchStatus(index,'Salvando mandado '+(index+1)+' de '+initialCount+'…');
      try{
        let result;
        if(entry.persistedWarrantId&&entry.uploadedDocumentPath){
          const {error}=await state.client.from('arrest_warrant_documents').insert({warrant_id:entry.persistedWarrantId,storage_path:entry.uploadedDocumentPath,file_name:entry.file.name.slice(0,220),content_type:'application/pdf',file_size_bytes:entry.file.size,created_by:state.session.user.id});
          if(error)throw error;
          result={id:entry.persistedWarrantId,reviewMessage:entry.reviewMessage||'',documentSaved:true,documentWarning:''};
        }else{
          result=await saveWarrantRecord(values,entry.file);
          if(!result.documentSaved&&result.documentPath){
            entry.persistedWarrantId=result.id;entry.uploadedDocumentPath=result.documentPath;entry.reviewMessage=result.reviewMessage;
            partial++;entry.status='Mandado criado; vínculo do PDF pendente. Toque em “Salvar mandados da fila” para tentar novamente.';
            warrantBatchStatus(index,entry.status);continue;
          }
        }
        entry.saved=true;saved++;if(result.duplicatePending)duplicateCount++;else if(result.reviewMessage)reviewCount++;
        entry.status=result.duplicatePending?'Possível duplicidade preservada para revisão administrativa.':'Mandado e PDF salvos.'+result.reviewMessage;
        warrantBatchStatus(index,entry.status);
      }catch(error){failed++;entry.status='Não concluído: '+msg(error);warrantBatchStatus(index,entry.status)}
    }
  }finally{warrantPdfBatchSaving=false}
  warrantPdfBatch=warrantPdfBatch.filter(entry=>!entry.saved);
  if(saved)warrantSearchResults.clear();
  await refreshWarrantReviewBadge();await renderWarrants();
  toast(saved+' arquivo(s) processado(s).'+(duplicateCount?' '+duplicateCount+' possível(is) duplicidade(s) preservada(s) para revisão administrativa.':'')+(reviewCount?' Confira as revisões administrativas pendentes na lista.':'')+(partial?' '+partial+' mandado(s) foram criados, mas o vínculo do PDF precisa de nova tentativa.':'')+(failed?' '+failed+' arquivo(s) permaneceram na fila para correção.':''));
}
