function duplicateReviewCard(entity,record){
  const vehicle=entity==='vehicles';
  const title=vehicle?[record.make,record.model,record.plate].filter(Boolean).join(' · '):record.full_name||'Indivíduo sem nome';
  const digitsOnly=String(record.cpf_digits||'').replace(/\D/g,'');
  const subtitle=vehicle?[record.color,record.plate].filter(Boolean).join(' · '):['CPF '+(digitsOnly.length===11?'***.***.***-'+digitsOnly.slice(-2):'—'),record.rg?'RG '+record.rg:'',record.birthday||''].filter(Boolean).join(' · ');
  const photo=record.photos?.find(item=>item.is_cover&&item.url)||record.photos?.find(item=>item.url);
  return '<button class="duplicate-record duplicate-mini-card" type="button" data-smart-open="'+esc(record.id)+'" data-smart-entity="'+entity+'" aria-label="Abrir '+esc(title)+'"><span class="duplicate-record-photo">'+(photo?'<img src="'+esc(photo.url)+'" alt="" loading="lazy">':'<span aria-hidden="true">'+(vehicle?'🚗':'♙')+'</span>')+'</span><span class="duplicate-record-info"><strong>'+esc(title)+'</strong><small>'+esc(subtitle||'Sem identificadores adicionais')+'</small></span><span class="duplicate-mini-open" aria-hidden="true">›</span></button>';
}
async function reviewDuplicatePair(pair,decision){
  if(!isAdmin())throw new Error('Acesso exclusivo para administradores.');
  const entity=pair.dataset.duplicateEntity,leftId=pair.dataset.leftId,rightId=pair.dataset.rightId;
  if(!entity||!leftId||!rightId)throw new Error('Não foi possível identificar os dois registros.');
  if(decision==='merge'){
    const group='primary-'+leftId+'-'+rightId,primary=pair.querySelector('input[name="'+CSS.escape(group)+'"]:checked')?.value;
    if(!primary)throw new Error('Escolha qual registro será mantido como principal.');
    if(!confirm('Juntar os cadastros? O escolhido será mantido; o outro será arquivado, com fotos, vínculos e histórico preservados.'))return;
    let error;
    if(entity==='people'){
      const fieldChoices={};
      for(const select of pair.querySelectorAll('[data-merge-field]'))fieldChoices[select.dataset.mergeField]=select.value===primary?'primary':'duplicate';
      ({error}=await state.client.rpc('admin_merge_people_with_choices',{p_primary_id:primary,p_duplicate_id:primary===leftId?rightId:leftId,p_field_choices:fieldChoices}));
    }else{
      ({error}=await state.client.rpc('admin_review_duplicate_records',{p_entity:entity,p_primary_id:primary,p_duplicate_id:primary===leftId?rightId:leftId,p_decision:'merge'}));
    }
    if(error)throw error;
    toast('Cadastros reunidos. O registro secundário foi arquivado e preservado.');
  }else{
    const {error}=await state.client.rpc('admin_review_duplicate_records',{p_entity:entity,p_primary_id:leftId,p_duplicate_id:rightId,p_decision:'separate'});
    if(error)throw error;
    toast('Registros marcados como distintos. Eles não aparecerão como duplicidade nesta revisão.');
  }
  await loadPage();
}
async function renderSmartReviewPage(){
  if(!isAdmin())throw new Error('Acesso exclusivo para administradores.');
  const loadAll=async(table,columns)=>{const out=[];for(let from=0;from<10000;from+=500){const {data,error}=await state.client.from(table).select(columns).is('archived_at',null).order('id').range(from,from+499);if(error)throw error;out.push(...(data||[]));if(!data||data.length<500)break}return out};
  const [people,vehicles,decisionsResult]=await Promise.all([
    loadAll('people','id,full_name,cpf_digits,rg,birthday,address_primary,photo_path,photo_paths'),
    loadAll('vehicles','id,plate,make,model,color,photo_path,photo_paths'),
    state.client.from('duplicate_record_reviews').select('entity,left_id,right_id,decision')
  ]);
  if(decisionsResult.error)throw new Error('A revisão de duplicidades precisa da migração administrativa antes de ser usada: '+msg(decisionsResult.error));
  const decisions=new Map((decisionsResult.data||[]).map(row=>[duplicateReviewPairKey(row.entity,row.left_id,row.right_id),row.decision]));
  const findings=inspectRecords(people,vehicles).filter(item=>!item.low);
  const duplicates=findings.filter(item=>item.duplicateId&&item.duplicateKind),ordinary=findings.filter(item=>!item.duplicateId);
  const byId={people:new Map(people.map(row=>[String(row.id),row])),vehicles:new Map(vehicles.map(row=>[String(row.id),row]))};
  const visibleDuplicates=duplicates.filter(item=>decisions.get(duplicateReviewPairKey(item.duplicateKind,item.id,item.duplicateId))!=='separate');
  const photoRecords={people:[],vehicles:[]};
  for(const item of visibleDuplicates)for(const id of [item.id,item.duplicateId]){const record=byId[item.duplicateKind].get(String(id));if(record&&!photoRecords[item.duplicateKind].includes(record))photoRecords[item.duplicateKind].push(record)}
  for(const entity of ['people','vehicles'])for(let offset=0;offset<photoRecords[entity].length;offset+=100)await galleryPhotosForRecords(entity,photoRecords[entity].slice(offset,offset+100));
  const openPairs=visibleDuplicates;
  const pairRows=openPairs.length?openPairs.map(item=>{
    const entity=item.duplicateKind,left=byId[entity].get(String(item.id)),right=byId[entity].get(String(item.duplicateId));
    if(!left||!right)return '';
    const group='primary-'+left.id+'-'+right.id;
    const mergeFields=entity==='people'?[['Nome','full_name'],['RG','rg'],['Matrícula','registration'],['Apelido','alias'],['Nascimento','birthday'],['Endereço principal','address_primary'],['Endereço secundário','address_secondary'],['Crimes','occurrence_notes'],['Referência','occurrence_reference'],['Características','characteristics']].filter(([,key])=>String(left[key]||'')&&String(right[key]||'')&&String(left[key])!==String(right[key])).map(([label,key])=>'<label class="merge-field-choice"><span>'+esc(label)+'</span><select data-merge-field="'+key+'"><option value="'+esc(left.id)+'">Manter: '+esc(String(left[key]).slice(0,70))+'</option><option value="'+esc(right.id)+'">Usar: '+esc(String(right[key]).slice(0,70))+'</option></select></label>').join(''):'';
    return '<article class="duplicate-review-pair" data-duplicate-pair data-duplicate-entity="'+entity+'" data-left-id="'+esc(left.id)+'" data-right-id="'+esc(right.id)+'"><header><div><strong>'+esc(item.label)+'</strong><small>'+esc(item.detail)+'</small></div><span class="duplicate-review-badge">Conferir</span></header><div class="duplicate-records">'+duplicateReviewCard(entity,left)+'<label class="duplicate-primary-choice"><input type="radio" name="'+esc(group)+'" value="'+esc(left.id)+'" checked><span>Manter como principal</span></label>'+duplicateReviewCard(entity,right)+'<label class="duplicate-primary-choice"><input type="radio" name="'+esc(group)+'" value="'+esc(right.id)+'"><span>Manter como principal</span></label></div>'+(mergeFields?'<details class="merge-field-panel"><summary>Escolher informação em conflito ('+((mergeFields.match(/class="merge-field-choice"/g)||[]).length)+')</summary>'+mergeFields+'<p class="muted">Fotos, vínculos e o registro secundário arquivado serão preservados.</p></details>':'')+'<footer><button class="button secondary" type="button" data-duplicate-decision="separate">Manter separados</button><button class="button" type="button" data-duplicate-decision="merge">Juntar cadastros</button></footer></article>';
  }).join(''):'<div class="empty">Nenhuma duplicidade pendente de decisão.</div>';
  const otherRows=ordinary.map(item=>'<article class="smart-finding"><div><strong>'+esc(item.label)+'</strong><small>'+esc(item.type)+' · '+esc(item.detail)+'</small></div><button class="button secondary small" type="button" data-smart-open="'+esc(item.id)+'" data-smart-entity="'+(item.type.startsWith('Veículo')?'vehicles':'people')+'">Revisar</button></article>').join('');
  frame('<section class="page-intro"><div><h1>Revisão Inteligente</h1><p>Confira os dois registros antes de decidir. A junção preserva o secundário arquivado, suas fotos, vínculos e histórico.</p></div></section><div class="stats"><div class="stat"><strong>'+people.length.toLocaleString('pt-BR')+'</strong><span>Indivíduos analisados</span></div><div class="stat"><strong>'+vehicles.length.toLocaleString('pt-BR')+'</strong><span>Veículos analisados</span></div><div class="stat"><strong>'+openPairs.length.toLocaleString('pt-BR')+'</strong><span>Duplicidades pendentes</span></div></div><section class="smart-review-list"><h2>Possíveis duplicidades</h2>'+pairRows+(otherRows?'<h2>Outros itens para conferência</h2>'+otherRows:'')+'</section>');
}
async function renderMaintenancePage(){
  if(!isAdmin())throw new Error('Acesso exclusivo para administradores.');
  const checks=[];
  const profile=await state.client.from('profiles').select('id,role').eq('id',state.session.user.id).single();
  checks.push({label:'Sessão administrativa',ok:!profile.error&&profile.data?.role==='admin',detail:profile.error?'Não foi possível confirmar o perfil.':'Perfil verificado no Supabase.'});
  for(const table of ['people','vehicles','record_photos','arrest_warrants']){
    const result=await state.client.from(table).select('id',{count:'exact',head:true});
    checks.push({label:'Acesso à tabela '+table,ok:!result.error,detail:result.error?'Falha de leitura: '+msg(result.error):'Consulta concluída; '+(result.count??0).toLocaleString('pt-BR')+' registros acessíveis.'});
  }
  const passed=checks.filter(c=>c.ok).length;
  frame('<section class="page-intro"><div><h1>Manutenção Inteligente</h1><p>Verificação real de conectividade e leitura do aplicativo, sem modificar dados.</p></div><button class="button" type="button" data-page="maintenance">Executar novamente</button></section><div class="notice">'+passed+' de '+checks.length+' verificações concluídas. Esta rotina não altera cadastros nem políticas.</div><section class="smart-checks">'+checks.map(c=>'<article class="smart-check '+(c.ok?'ok':'failed')+'"><strong>'+(c.ok?'✓':'!')+' '+esc(c.label)+'</strong><small>'+esc(c.detail)+'</small></article>').join('')+'</section><p class="muted">Esta página não afirma que OCR, fotos, backups ou tarefas agendadas foram verificados. Esses itens exigem testes específicos ou infraestrutura adicional.</p>');
}
async function findSmartBundleCandidates(kind,values){
  if(kind==='person'){
    if(values.cpf_digits&&values.cpf_digits.length===11){const {data,error}=await state.client.from('people').select('*').eq('cpf_digits',values.cpf_digits).is('archived_at',null).limit(8);if(error)throw error;return data||[]}
    const terms=getSmartPersonSearchTerms(values);const results=await Promise.all(terms.map(search_term=>state.client.rpc('search_people',{search_term,result_limit:8})));const rows=new Map();for(const result of results){if(result.error)throw result.error;for(const row of result.data||[])rows.set(row.id,row)}return [...rows.values()].slice(0,8)
  }
  if(!values.plate)return [];
  const {data,error}=await state.client.rpc('search_vehicles',{search_term:values.plate,result_limit:8});if(error)throw error;
  const plate=normalizePlate(values.plate);return (data||[]).filter(row=>normalizePlate(row.plate)===plate&&row.archived_at==null)
}
function smartBundleChoiceMarkup(kind,records,values){
  const exact=records.find(row=>kind==='person'?String(row.cpf_digits||'').replace(/\D/g,'')===values.cpf_digits&&values.cpf_digits.length===11:normalizePlate(row.plate)===normalizePlate(values.plate));
  const options=records.map(row=>{
    const photo=row.photos?.find(item=>item.is_cover&&item.url)||row.photos?.find(item=>item.url);
    const title=kind==='person'?row.full_name:[row.make,row.model,row.plate].filter(Boolean).join(' ');
    const sub=kind==='person'?'CPF '+(String(row.cpf_digits||'').replace(/\D/g,'').length===11?formatCpf(row.cpf_digits):'—')+' · '+(row.birthday||''):['Placa '+row.plate,row.color].filter(Boolean).join(' · ');
    return '<label class="smart-bundle-record"><input type="radio" name="smart-bundle-'+kind+'" value="'+esc(row.id)+'" '+(exact?.id===row.id?'checked':'')+'><span class="smart-bundle-thumb">'+(photo?'<img src="'+esc(photo.url)+'" alt="" loading="lazy">':(kind==='person'?'♙':'🚗'))+'</span><span><strong>'+esc(title||'Cadastro')+'</strong><small>'+esc(sub)+'</small></span></label>'
  }).join('');
  const newChecked=exact?'':'checked';
  return '<section class="smart-bundle-section"><h3>'+(kind==='person'?'👤 Indivíduo':'🚗 Veículo')+'</h3>'+options+'<label class="smart-bundle-record smart-bundle-new"><input type="radio" name="smart-bundle-'+kind+'" value="new" '+newChecked+'><span class="smart-bundle-thumb">'+(kind==='person'?'＋':'＋')+'</span><span><strong>Criar novo '+(kind==='person'?'indivíduo':'veículo')+'</strong><small>Os dados serão conferidos antes de salvar.</small></span></label><div class="smart-fields">'+Object.entries(values).filter(([,v])=>v!==undefined).map(([key,value])=>'<label class="field"><span>'+esc(({full_name:'Nome',cpf_digits:'CPF',rg:'RG',birthday:'Nascimento',address_primary:'Endereço',notes:'Anotações',plate:'Placa',make:'Marca',model:'Modelo',color:'Cor'})[key]||key)+'</span><input data-bundle-value="'+kind+'" data-bundle-key="'+key+'" value="'+esc(value||'')+'"></label>').join('')+'</div></section>'
}
async function analyzeSmartBundleEntry(raw){
 const parsed=parseIntelligentBundle(raw);
 if(!parsed.hasPerson||!parsed.hasVehicle)return false;
 const result=$('#smartResult');if(result)result.innerHTML='<div class="notice">Verificando indivíduos e veículos…</div>';
 const [people,vehicles]=await Promise.all([findSmartBundleCandidates('person',parsed.person),findSmartBundleCandidates('vehicle',parsed.vehicle)]);
 await Promise.all([galleryPhotosForRecords('people',people),galleryPhotosForRecords('vehicles',vehicles)]);
 state.smartBundle={person:parsed.person,vehicle:parsed.vehicle,people,vehicles};
 const target=$('#smartResult');if(!target)return true;
 target.innerHTML='<section class="smart-analysis"><h2>Confira pessoa e veículo</h2><p class="muted">A pesquisa verificou os dois registros. Escolha um cadastro existente ou “Criar novo” para cada um; a associação só será feita depois da confirmação e do salvamento.</p>'+smartBundleChoiceMarkup('person',people,parsed.person)+smartBundleChoiceMarkup('vehicle',vehicles,parsed.vehicle)+'<label class="field smart-bundle-relation"><span>Relação sugerida</span><select id="smartBundleRelation"><option value="associated">Associado</option><option value="driver">Condutor</option><option value="owner">Proprietário</option></select></label><button class="button" type="button" id="smartBundleConfirm">Confirmar e continuar</button></section>';requestAnimationFrame(()=>target.scrollIntoView({behavior:'smooth',block:'start'}));
 return true
}
async function ensureSmartAssociation(personId,vehicleId,relation='associated'){
  const found=await state.client.from('person_vehicle_links').select('id').eq('person_id',personId).eq('vehicle_id',vehicleId).eq('relation',relation).eq('active',true).maybeSingle();
  if(found.error)throw found.error;if(found.data)return found.data.id;
  const inserted=await state.client.from('person_vehicle_links').insert({person_id:personId,vehicle_id:vehicleId,relation,notes:'',created_by:state.session.user.id}).select('id').single();
  if(inserted.error)throw inserted.error;return inserted.data.id
}
async function continueSmartBundle(){
  const bundle=state.smartBundle;if(!bundle)throw new Error('Analise os dados de pessoa e veículo primeiro.');
  const read=(kind)=>{const values={};for(const input of document.querySelectorAll('[data-bundle-value="'+kind+'"]'))values[input.dataset.bundleKey]=input.value.trim();return values};
  const personValues=read('person'),vehicleValues=read('vehicle'),personChoice=document.querySelector('[name="smart-bundle-person"]:checked')?.value||'new',vehicleChoice=document.querySelector('[name="smart-bundle-vehicle"]:checked')?.value||'new',relation=$('#smartBundleRelation')?.value||'associated';
  if(!personValues.full_name||!vehicleValues.plate)throw new Error('Confira o nome da pessoa e a placa do veículo.');
  if(personChoice==='new'&&bundle.people.some(row=>String(row.cpf_digits||'').replace(/\D/g,'')===String(personValues.cpf_digits||'').replace(/\D/g,'')&&String(personValues.cpf_digits||'').replace(/\D/g,'').length===11))throw new Error('Esse CPF já existe. Selecione o cadastro encontrado para não criar duplicidade.');
  if(vehicleChoice==='new'&&bundle.vehicles.some(row=>normalizePlate(row.plate)===normalizePlate(vehicleValues.plate)))throw new Error('Essa placa já existe. Selecione o veículo encontrado para não criar duplicidade.');
  const existingPerson=personChoice==='new'?null:bundle.people.find(row=>String(row.id)===personChoice);
  const existingVehicle=vehicleChoice==='new'?null:bundle.vehicles.find(row=>String(row.id)===vehicleChoice);
  if(existingPerson&&existingVehicle){await ensureSmartAssociation(existingPerson.id,existingVehicle.id,relation);toast('Registros conferidos e associação confirmada.');await openPerson(existingPerson.id);return}
  if(existingPerson){await showForm('vehicle',null,{initialValues:vehicleValues,initialPlate:vehicleValues.plate,initialPersonId:existingPerson.id,initialRelation:relation,focusPhotos:true,smartEntry:true});return}
  if(existingVehicle){await showForm('person',null,{initialValues:personValues,focusPhotos:true,smartEntry:true,onSaved:async(_kind,personId)=>{await ensureSmartAssociation(personId,existingVehicle.id,relation);toast('Indivíduo salvo e associação confirmada.');await openPerson(personId)}});return}
  await showForm('person',null,{initialValues:personValues,focusPhotos:true,smartEntry:true,onSaved:async(_kind,personId)=>{await showForm('vehicle',null,{initialValues:vehicleValues,initialPlate:vehicleValues.plate,initialPersonId:personId,initialRelation:relation,focusPhotos:true,smartEntry:true})}})
}
function renderSmartCandidates(kind,values,candidates){
  const person=kind==='person';
  const fields=person
    ?[['full_name','Nome'],['cpf_digits','CPF'],['rg','RG'],['birthday','Nascimento'],['address_primary','Endereço'],['notes','Anotações']]
    :[['plate','Placa'],['make','Marca'],['model','Modelo'],['color','Cor'],['notes','Anotações']];
  const fieldsMarkup=fields.map(([key,label])=>{
    const value=values?.[key]??'';
    if(!value)return '';
    return '<label class="field"><span>'+esc(label)+'</span><input data-smart-value="'+esc(key)+'" value="'+esc(value)+'" autocomplete="off"></label>'
  }).join('');
  const exactMatch=Boolean(state.smartExactMatch);
  const cards=(candidates||[]).map(row=>{
    const photo=(row.photos||[]).find(item=>item.is_cover&&item.url)||(row.photos||[]).find(item=>item.url);
    const name=person?(row.full_name||'Indivíduo sem nome'):[row.make,row.model].filter(Boolean).join(' ')||'Veículo';
    const detail=person
      ?'CPF: '+(row.cpf_digits?formatCpf(row.cpf_digits):'—')+(row.rg?' · RG: '+row.rg:'')
      :'Placa: '+(row.plate||'—')+(row.color?' · '+row.color:'');
    return '<button class="smart-mini-card" type="button" data-smart-existing="'+esc(row.id)+'" data-smart-kind="'+(person?'person':'vehicle')+'"><span class="smart-candidate-photo">'+(photo?'<img src="'+esc(photo.url)+'" alt="" loading="lazy">':(person?'♙':'🚗'))+'</span><span class="smart-candidate-copy"><strong>'+esc(name)+'</strong><small>'+esc(detail)+'</small></span><span class="smart-candidate-chevron" aria-hidden="true">›</span></button>'
  }).join('');
  const duplicateNotice=exactMatch
    ?'<div class="notice warning">Já existe cadastro com este '+(person?'CPF':'placa')+'. Abra o registro encontrado para editar e evitar duplicidade.</div>'
    :candidates?.length
      ?'<div class="notice">Encontramos registros possivelmente relacionados. Confira antes de continuar.</div>'
      :'<div class="notice">Nenhuma correspondência encontrada. Confira os dados e avance para as fotos.</div>';
  return '<section class="smart-analysis"><h2>Confira os dados identificados</h2>'+duplicateNotice+
    (cards?'<div class="smart-candidate-list"><h3>Cadastros encontrados</h3>'+cards+'</div>':'')+
    '<div class="smart-fields">'+(fieldsMarkup||'<p class="muted">Não foi possível identificar campos. Você poderá preencher no formulário.</p>')+'</div>'+
    '<div class="smart-actions">'+(exactMatch?'':'<button class="button" type="button" data-smart-continue="'+(person?'person':'vehicle')+'">'+(candidates?.length?'Criar novo mesmo assim':'Continuar para fotos e cadastro')+'</button>')+'</div></section>'
}
async function analyzeSmartEntry(){
 const kind=document.querySelector('[data-smart-kind].active')?.dataset.smartKind||'person',raw=document.querySelector('#smartText')?.value||'';
 if(!raw.trim()){toast('Digite as informações antes de analisar.');return}
 if(await analyzeSmartBundleEntry(raw))return;
 const values=parseIntelligentText(kind,raw),table=kind==='person'?'people':'vehicles',key=kind==='person'?'cpf_digits':'plate';
 let candidates=[];
 if(kind==='person'&&values.cpf_digits.length===11){
   const result=await state.client.from(table).select('*').eq(key,values.cpf_digits).is('archived_at',null).limit(8);
   if(result.error)throw result.error;candidates=result.data||[];
 }else if(kind==='person'){
   const terms=getSmartPersonSearchTerms(values);
   const results=await Promise.all(terms.map(search_term=>state.client.rpc('search_people',{search_term,result_limit:12})));
   const unique=new Map();
   for(const result of results){if(result.error)throw result.error;for(const row of result.data||[])unique.set(row.id,row)}
   candidates=[...unique.values()].slice(0,12);
 }else if(values.plate){
   const result=await state.client.from(table).select('*').ilike('plate',values.plate).is('archived_at',null).limit(8);
   if(result.error)throw result.error;candidates=result.data||[];
 }
 state.smartParsed=values;
 state.smartExactMatch=kind==='person'&&values.cpf_digits.length===11
   ?candidates.some(row=>String(row.cpf_digits||'').replace(/\D/g,'')===values.cpf_digits)
   :kind==='vehicle'&&Boolean(values.plate)&&candidates.some(row=>normalizePlate(row.plate)===normalizePlate(values.plate));
 state.smartMatchesCount=candidates.length;
 await galleryPhotosForRecords(table,candidates);
 if(!candidates.length){toast('Nenhuma duplicidade encontrada. Continue o cadastro.');await showForm(kind==='person'?'person':'vehicle',null,{initialValues:values,focusPhotos:true,smartEntry:true});return}
 const result=$('#smartResult');if(result){result.innerHTML=renderSmartCandidates(kind,values,candidates);requestAnimationFrame(()=>result.scrollIntoView({behavior:'smooth',block:'start'}))}
}

async function continueSmartEntry(kind){
  const values=Object.fromEntries([...document.querySelectorAll('[data-smart-value]')].map(input=>[input.dataset.smartValue,input.value.trim()]));
  if(kind==='person'&&!values.full_name){toast('Informe o nome do indivíduo antes de continuar.');return}
  if(kind==='vehicle'&&!values.plate){toast('Informe a placa antes de continuar.');return}
  if(state.smartExactMatch){toast(kind==='person'?'Este CPF já está cadastrado. Confira o registro existente.':'Esta placa já está cadastrada. Confira o veículo existente.');return}
  const allowSimilarNameDuplicate=state.smartMatchesCount>0&&window.confirm('A pesquisa encontrou possíveis cadastros semelhantes. Você conferiu os resultados e confirma que este é outro cadastro?');
  if(state.smartMatchesCount>0&&!allowSimilarNameDuplicate)return;
  await showForm(kind==='person'?'person':'vehicle',null,{initialValues:values,focusPhotos:true,smartEntry:true,allowSimilarNameDuplicate});
}
