async function applyPhotoEdits(entity,record,form){if(!isAdmin())return true;const current=await galleryPhotos(entity,record),deleted=[...form.querySelectorAll('[data-edit-delete-photo]:checked')].map(input=>({id:input.dataset.editDeletePhoto,path:input.dataset.deletePath})),removing=new Set(deleted.map(photo=>photo.path)),remaining=current.filter(photo=>!removing.has(photo.photo_path)),requestedPath=form.querySelector('[name="editCoverPhoto"]:checked')?.dataset.editCoverPath,cover=remaining.find(photo=>photo.photo_path===requestedPath)||remaining.find(photo=>photo.is_cover)||remaining[0]||null;const {error:clearError}=await state.client.from('record_photos').update({is_cover:false}).eq('entity',entity).eq('entity_id',record.id);if(clearError){toast(msg(clearError));return false}if(cover?.id){const {error}=await state.client.from('record_photos').update({is_cover:true}).eq('id',cover.id);if(error){toast(msg(error));return false}}const {error:recordError}=await state.client.from(entity).update({photo_path:cover?.photo_path||null,updated_by:state.session.user.id}).eq('id',record.id);if(recordError){toast(msg(recordError));return false}const rowIds=deleted.map(photo=>photo.id).filter(id=>id&&id!=='legacy');if(rowIds.length){const {error}=await state.client.from('record_photos').delete().in('id',rowIds);if(error){toast(msg(error));return false}}const legacy=deleted.filter(photo=>!photo.id||photo.id==='legacy').map(photo=>photo.path);if(legacy.length){const table=entity==='people'?'person_photos':'vehicle_photos',key=entity==='people'?'person_id':'vehicle_id';const {error}=await state.client.from(table).delete().eq(key,record.id).in('photo_path',legacy);if(error&&!['42P01','PGRST205','PGRST204'].includes(error.code||'')){toast(msg(error));return false}}const storedPaths=deleted.map(photo=>photo.path).filter(path=>path&&!externalPhotoUrl(path));if(storedPaths.length){const result=await removeUnreferencedPhotoFiles(storedPaths);if(result.error)toast('As fotos saíram do cadastro, mas alguns arquivos foram mantidos porque não foi possível verificar se pertencem a outro registro.');else if(result.kept)toast('As fotos foram removidas deste cadastro; arquivos usados por outros registros foram preservados.')}if(deleted.length){dashboardPhotoStatsAt=0;await clearPhotoCache(state.session.user.id)}return true}
